import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene placement
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load texture from configuration
  const imageTexture = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/feature-card.png');
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  // Plane geometry with 512:320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Material using TSL texture node
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(imageTexture),
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply cinematic primitives if configured
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    }
  }

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  // Event handlers container
  group.userData.handlers = {};

  return group;
}
